import{_ as a,C as e,o as l,c as r,aj as p,G as n,j as s}from"./chunks/framework.BZR1KcQy.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"docs/wi/altsp/44.safe_sett.md","filePath":"docs/wi/altsp/44.safe_sett.md","lastUpdated":1788534566000}'),i={name:"docs/wi/altsp/44.safe_sett.md"};function c(d,t,u,m,h,f){const o=e("ImageZoom");return l(),r("div",null,[t[0]||(t[0]=p('<p>Операционная система должна предоставлять ==упреждающие меры защиты и быть сконфигурирована с безопасными настройками по умолчанию==.</p><hr><ol start="96"><li>Режим суперпользователя</li></ol><p><a href="https://docs.altlinux.org/ru-RU/alt-kworkstation/10.4/html/alt-kworkstation/admin-basics--sumode--chapter.html" target="_blank" rel="noreferrer">https://docs.altlinux.org/ru-RU/alt-kworkstation/10.4/html/alt-kworkstation/admin-basics--sumode--chapter.html</a></p><ol start="2"><li>Невозможность завести пользователя с пустым паролем</li></ol><p>Запрет root ходить по ssh</p><p>Был вскрыт образ Альт СП, вот список некоторых скриптов:</p><p><code>/home/basealt/altcustom/squashfs-root/usr/share/install2/postinstall.d/40-add-trusted-mode.sh</code> - добавление доверенных интерпретаторов питон и перл</p><p><code>/home/basealt/altcustom/squashfs-root/usr/share/install2/postinstall.d/86-all-groups</code> - создание групп</p><p><code>/home/basealt/altcustom/squashfs-root/usr/share/install2/preinstall.d/08-crypttab.sh</code> - отработка LUKS</p><p><code>/home/basealt/altcustom/squashfs-root/usr/share/install2/preinstall.d/80-setup-user-groups</code> - создание основных групп</p><p><code>/home/basealt/altcustom/squashfs-root/usr/share/polkit-1</code> - настройки политик Polkit</p><p><code>/home/basealt/altcustom/squashfs-root/lib/sysctl.d</code> - service to configure sysctl kernel parameters. управление параметрами ядра</p><p><code>/home/basealt/altcustom/squashfs-root/usr/share/pki/ca-trust-source</code> - сертификаты и доверенные настройки</p><p><code>/home/basealt/altcustom/squashfs-root/usr/share/install2/postinstall.d/90-integrity-init.sh</code> - инициализация базы данных OSEC</p><p><code>/home/basealt/altcustom/squashfs-root/usr/share/install2/postinstall.d/45-noexec-home.sh</code> - занесение записей о монтировании /home и /tmp с параметром noexec</p><p><code>/home/basealt/altcustom/squashfs-root/usr/share/install2/initinstall.d/01-apt-cache-limit.sh</code> - ограничение кэша apt</p><p>запуск через чрут</p><p>! По умолчанию включен только репозиторий с установочного диска, даже внешний altsp.su выключен</p><p>! логирование и журналированине</p><p>В Альт 8СП релиз 10 по умолчанию В целях повышения уровня безопасности домашний каталог пользователя /home, а также каталог /tmp, смонтирован с опцией noexec (вам не будет доступен запуск скриптов, некоторые изменения в системе, могут возникнуть проблемы при установке отдельного ПО).</p><p><a href="https://www.altlinux.org/Control" target="_blank" rel="noreferrer">https://www.altlinux.org/Control</a></p><p>Работа в системе с использованием учетной записи администратора небезопасна, вследствие этого вход в систему в графическом режиме для администратора (root) запрещен. Попытка зарегистрироваться в системе будет прервана сообщением об ошибке.</p><p>Своя схема работы с паролями <a href="https://www.altlinux.org/Tcb" target="_blank" rel="noreferrer">https://www.altlinux.org/Tcb</a></p><p>Я надеялся, что хоть фаерволл по умолчанию нормально сделан, но</p>',25)),n(o,{src:"/img/iptab.png"}),t[1]||(t[1]=s("p",null,"по умолчанию он выключен)",-1)),t[2]||(t[2]=s("p",null,"могу ещё вспомнить, естественно, про изоляцию, пользовательское пространство, разграничение доступа и т.д. и т.п.:",-1)),t[3]||(t[3]=s("p",null,"![[23) Изолированные сеансы]]",-1))])}const w=a(i,[["render",c]]);export{b as __pageData,w as default};
